#include <bits/stdc++.h>
using namespace std;

int main() {
    const long long MOD = 1000000007;
    long long n;
    cin >> n;
    long long e = n * (n - 1) / 2; // one independent optional edge per vertex pair
    long long result = 1, base = 2 % MOD;
    while (e > 0) {
        if (e & 1) result = result * base % MOD;
        base = base * base % MOD;
        e >>= 1;
    }
    cout << result << "\n";
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        final long MOD = 1000000007L;
        long n = new Scanner(System.in).nextLong();
        long e = n * (n - 1) / 2; // one independent optional edge per vertex pair
        long result = 1, base = 2;
        while (e > 0) {
            if ((e & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            e >>= 1;
        }
        System.out.println(result);
    }
}

package main

import "fmt"

func main() {
	const mod = 1000000007
	var n int64
	fmt.Scan(&n)
	e := n * (n - 1) / 2 // one independent optional edge per vertex pair
	result, base := int64(1), int64(2)
	for e > 0 {
		if e&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		e >>= 1
	}
	fmt.Println(result)
}
